import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { createSession, getSession, resetSessions, revokeSession } from "../src/auth/session.ts";

const HOUR = 60 * 60 * 1000;

beforeEach(() => resetSessions());

test("createSession issues a unique token bound to the user", () => {
  const a = createSession("u_1", { ttlMs: HOUR });
  const b = createSession("u_1", { ttlMs: HOUR });
  assert.equal(a.userId, "u_1");
  assert.notEqual(a.token, b.token);
  assert.equal(a.expiresAt, a.createdAt + HOUR);
  assert.equal(getSession(a.token)?.userId, "u_1");
});

test("revokeSession ends the session", () => {
  const s = createSession("u_2", { ttlMs: HOUR });
  assert.equal(revokeSession(s.token), true);
  assert.equal(getSession(s.token), undefined);
});

test("getSession forgets a session once it expires", (t) => {
  t.mock.timers.enable({ apis: ["Date"], now: 1_000 });
  const s = createSession("u_3", { ttlMs: 500 });
  t.mock.timers.tick(499);
  assert.equal(getSession(s.token)?.userId, "u_3");
  t.mock.timers.tick(1);
  assert.equal(getSession(s.token), undefined);
  // Forgotten: still gone even if the clock were to move back.
  t.mock.timers.setTime(1_000);
  assert.equal(getSession(s.token), undefined);
});

