import { randomBytes } from "node:crypto";

export type Session = { token: string; userId: string; createdAt: number; expiresAt: number };

export type SessionOptions = { ttlMs: number };

/** Default session lifetime, used when no options are given (e.g. refreshed sessions). */
export const DEFAULT_SESSION_OPTIONS: SessionOptions = { ttlMs: 60 * 60 * 1000 };

const sessions = new Map<string, Session>();

/** Start a session for a user and return it (the token is the bearer credential). */
export function createSession(userId: string, opts: SessionOptions = DEFAULT_SESSION_OPTIONS): Session {
  const createdAt = Date.now();
  const session: Session = {
    token: randomBytes(24).toString("base64url"),
    userId,
    createdAt,
    expiresAt: createdAt + opts.ttlMs,
  };
  sessions.set(session.token, session);
  return session;
}

/** The live session for a token, or undefined (expired sessions are forgotten). */
export function getSession(token: string): Session | undefined {
  const session = sessions.get(token);
  if (session && Date.now() >= session.expiresAt) {
    sessions.delete(token);
    return undefined;
  }
  return session;
}

export function revokeSession(token: string): boolean {
  return sessions.delete(token);
}

/** Test helper: forget every session. */
export function resetSessions(): void {
  sessions.clear();
}

import { authenticate } from "../auth/users.ts";
import { createSession } from "../auth/session.ts";
import { accountRoutes } from "./account.ts";
import { createRouter, field, html, json, type Route } from "./router.ts";
import { loginPage } from "../ui/pages.ts";

/** POST /api/login {email, password} -> {token} */
export function login(email: string, password: string): { token: string } | undefined {
  const user = authenticate(email, password);
  if (!user) return undefined;
  const session = createSession(user.id, { ttlMs: 60 * 60 * 1000 });
  return { token: session.token };
}

export const routes: Route[] = [
  { method: "GET", path: "/", handler: () => html(200, loginPage()) },
  { method: "GET", path: "/api/health", handler: () => json(200, { ok: true }) },
  {
    method: "POST",
    path: "/api/login",
    handler: (req) => {
      const email = field(req.body, "email");
      const password = field(req.body, "password");
      if (!email || !password) return json(400, { error: "email and password are required" });
      const result = login(email, password);
      return result ? json(200, result) : json(401, { error: "invalid credentials" });
    },
  },
  ...accountRoutes,
];

export const app = createRouter(routes);

